      {:error, reason} -> {:error, [message: reason, reason: reason]}
    end
  end
  def cast_input(str, _) when is_binary(str) do
    case String.split(String.trim(str), " ") do
      [c_str, a_str] ->
        with {:ok, currency} <- resolve_currency(c_str),
             {:ok, amount} <- parse_string_amount(a_str, currency) do
          {:ok, Ledger.Money.new!(amount, currency)}
        else
          {:error, reason, meta} -> {:error, [{:message, reason}, {:reason, meta}] ++ extra(meta)}
          {:error, reason} -> {:error, [message: reason, reason: reason]}
        end
      _ -> {:error, [message: "invalid money format", reason: :invalid_format]}
    end
  end
  def cast_input(_, _), do: {:error, [message: "invalid money format", reason: :invalid_format]}

  defp extra(:unknown_currency), do: []
  defp extra(_), do: []

  defp resolve_currency(nil), do: {:error, "invalid money format", :invalid_format}
  defp resolve_currency(c) when is_atom(c) do
    if c in Ledger.Money.currencies(), do: {:ok, c}, else: {:error, "unknown currency", :unknown_currency}
  end
  defp resolve_currency(c) when is_binary(c) do
    c_up = String.downcase(c)
    target = Enum.find(Ledger.Money.currencies(), &(Atom.to_string(&1) == c_up))
    if target, do: {:ok, target}, else: {:error, "unknown currency", :unknown_currency}
  end
  defp resolve_currency(_), do: {:error, "invalid money format", :invalid_format}

  defp resolve_amount(i) when is_integer(i), do: {:ok, i}
  defp resolve_amount(s) when is_binary(s) do
    if String.match?(s, ~r/^-?[0-9]+$/), do: {:ok, String.to_integer(s)}, else: {:error, "invalid money format", :invalid_format}
  end
  defp resolve_amount(_), do: {:error, "amount must be a whole number of minor units", :fractional_minor_units}

  defp parse_string_amount(s, currency) do
    exponent = Ledger.Money.exponent(currency)
    if String.match?(s, ~r/^-?[0-9]+\.[0-9]+$/) do
      {:error, "amount must be a whole number of minor units", :fractional_minor_units}
    else
      with {:ok, amount} <- resolve_amount(s) do
        {:ok, amount}
      else
        {:error, reason, meta} -> {:error, reason, meta}
        {:error, reason} -> {:error, reason}
      end
    end
  end

  @impl true
  def dump(nil, _, _), do: {:ok, nil}
  def dump(%Ledger.Money{currency: c, amount: a}, _, _), do: {:ok, %{"currency" => Atom.to_string(c), "amount" => a}}
  def dump(_, _, _), do: {:error, [message: "invalid money format", reason: :invalid_format]}

  @impl true
  def load(nil, _, _), do: {:ok, nil}
  def load(%{"currency" => c, "amount" => a}, _, _) when is_binary(c) and is_integer(a) do
    case resolve_currency(c) do
      {:ok, currency} -> {:ok, Ledger.Money.new!(a, currency)}
      _ -> {:error, [message: "invalid money format", reason: :invalid_format]}
    end
  end
  def load(_, _, _), do: {:error, [message: "invalid money format", reason: :invalid_format]}

  @impl true
  def apply_constraints(nil, _, _), do: {:ok, nil}
  def apply_constraints(value, constraints, _) do
    with {:ok, value} <- check_currencies(value, constraints),
         {:ok, value} <- check_multiple(value, constraints),
         {:ok, value} <- check_min(value, constraints),
         {:ok, value} <- check_max(value, constraints) do
      {:ok, value}
    end
  end

  defp check_currencies(m, opts) do
    allowed = opts[:currencies]
    if allowed && m.currency not in allowed do
      {:error, [message: "currency is not allowed", reason: :currency_not_allowed, currency: m.currency]}
    else
      {:ok, m}
    end
  end

  defp check_multiple(m, opts) do
    mult = opts[:multiple_of]
    if mult && rem(m.amount, mult) != 0 do
      {:error, [message: "must be a multiple of %{multiple_of} minor units", reason: :not_multiple_of, multiple_of: mult]}
    else
      {:ok, m}
    end
  end

  defp check_min(m, opts) do
    bound = opts[:min]
    if bound do
      compare_bound(m, bound, :below_min, "must be greater than or equal to %{min}", :min)
    else
      {:ok, m}
    end
  end

  defp check_max(m, opts) do
    bound = opts[:max]
    if bound do
      compare_bound(m, bound, :above_max, "must be less than or equal to %{max}", :max)
    else
      {:ok, m}
    end
  end

  defp compare_bound(m, bound, reason, msg, key) do
    case cast_input(bound, []) do
      {:ok, b_money} ->
        if m.currency != b_money.currency do
          {:error, [message: "cannot compare money in different currencies", reason: :currency_mismatch]}
        else
          if Ledger.Money.compare(m, b_money) == :lt and reason == :below_min do
            {:error, [message: msg, reason: reason, min: Ledger.Money.to_string(b_money)]}
          else
            if Ledger.Money.compare(m, b_money) == :gt and reason == :above_max do
              {:error, [message: msg, reason: reason, max: Ledger.Money.to_string(b_money)]}
            else
              {:ok, m}
            end
          end
        end
      _ -> {:ok, m}
    end
  end
end
