defmodule Ledger.Money do
  @moduledoc """
  Exact-integer money type: {currency, minor_units}.
  """

  defstruct [:currency, :amount]

  @typedoc "Money value in minor units for a specific currency."
  @type t :: %__MODULE__{currency: atom(), amount: integer()}

  @currencies %{
    bhd: 3,
    eur: 2,
    jpy: 0,
    usd: 2
  }
  @currency_order Map.keys(@currencies)

  @spec currencies() :: [atom()]
  def currencies, do: @currency_order

  @spec exponent(atom()) :: integer()
  def exponent(c) when is_atom(c) do
    case Map.fetch(@currencies, c) do
      {:ok, e} -> e
      :error -> raise ArgumentError, "unknown currency: #{inspect(c)}"
    end
  end

  @spec new(integer(), atom()) :: {:ok, t()} | {:error, :invalid_amount | :unknown_currency}
  def new(amount, currency) when is_atom(currency) do
    cond do
      not is_integer(amount) -> {:error, :invalid_amount}
      Map.has_key?(@currencies, currency) -> {:ok, %__MODULE__{currency: currency, amount: amount}}
      true -> {:error, :unknown_currency}
    end
  end

  @spec new!(integer(), atom()) :: t()
  def new!(amount, currency) do
    case new(amount, currency) do
      {:ok, money} -> money
      {:error, reason} -> raise ArgumentError, "cannot build money: #{inspect(reason)}"
    end
  end

  @spec zero(atom()) :: t()
  def zero(currency), do: %__MODULE__{currency: currency, amount: 0}

  @spec add(t(), t()) :: {:ok, t()} | {:error, :currency_mismatch}
  def add(m1, m2), do: op(&Kernel.+/2, m1, m2)

  @spec subtract(t(), t()) :: {:ok, t()} | {:error, :currency_mismatch}
  def subtract(m1, m2), do: op(&Kernel.-/2, m1, m2)

  @spec multiply(t(), any()) :: {:ok, t()} | {:error, :invalid_factor}
  def multiply(%__MODULE__{} = m, factor) when is_integer(factor) do
    {:ok, %{m | amount: m.amount * factor}}
  end
  def multiply(%__MODULE__{}, _), do: {:error, :invalid_factor}

  @spec sum([t()], atom()) :: {:ok, t()} | {:error, :currency_mismatch}
  def sum(list, currency) when is_list(list) do
    Enum.reduce(list, {:ok, zero(currency)}, fn m, acc ->
      case {acc, m} do
        {{:ok, a}, %__MODULE__{currency: c}} when c == currency -> {:ok, %{a | amount: a.amount + m.amount}}
        _ -> {:error, :currency_mismatch}
      end
    end)
  end

  @spec compare(t(), t()) :: :lt | :eq | :gt
  def compare(m1, m2) do
    if m1.currency != m2.currency, do: raise(ArgumentError, "currency mismatch")
    cond do
      m1.amount < m2.amount -> :lt
      m1.amount > m2.amount -> :gt
      true -> :eq
    end
  end

  @spec to_string(t()) :: String.t()
  def to_string(%__MODULE__{currency: c, amount: a}) do
    e = Map.fetch!(@currencies, c)
    s = Integer.to_string(abs(a))
    pad = String.pad_leading(s, e + 1, "0")
    {int, frac} = if e > 0, do: String.split_at(pad, -e), else: {pad, ""}
    res = if frac == "", do: int, else: int <> "." <> frac
    prefix = if a < 0, do: "-", else: ""
    "#{String.upcase(Atom.to_string(c))} #{prefix}#{res}"
  end

  defimpl String.Chars do
    def to_string(m), do: Ledger.Money.to_string(m)
  end

  defimpl Inspect do
    import Inspect.Algebra
    def inspect(m, opts) do
      concat(["#Ledger.Money<", to_doc(Ledger.Money.to_string(m), opts), ">"])
    end
  end

  defp op(func, %__MODULE__{currency: c1, amount: a1}, %__MODULE__{currency: c2, amount: a2}) do
    if c1 == c2, do: {:ok, %__MODULE__{currency: c1, amount: func.(a1, a2)}}, else: {:error, :currency_mismatch}
  end
end
